css:
  /* Page + typography */
  :root{
    --navy:#0f2e5f;
    --grid:#bfc9d6;
    --label1:#d9d9d9;  /* left grey (group) */
    --label2:#f4f6f9;  /* middle label cells */
    --text:#111;
  }
  @page { size: A4; margin: 18mm; }
  html,body{ height:100%; }
  body{
    margin:0;
    color:var(--text);
    font: 12px "Arial Narrow", Arial, Helvetica, sans-serif;
    background:#fff;
  }

  .page{
    width: 100%;             /* take full printable width */
    max-width: 210mm;          /* A4 width */
    margin: 0 auto;
    padding: 12mm 8mm;
    box-sizing: border-box;
  }


  h1{
    font-weight:700;
    font-size: 14px;
    margin: 0 0 8px 0;
  }

  /* Table */
  .doc-table{
    width:100%;
    border-collapse: collapse;
    table-layout: fixed;
    border: 1px solid var(--grid);
  }

  /* Section header bar */
  .section-head th{
    background: var(--navy);
    color: #fff;
    text-align: left;
    padding: 6px 8px;
    font-weight: 700;
    border: 1px solid var(--navy);
    font-size: 12px;
  }

  /* Base cells */
  .doc-table td, .doc-table th{
    border: 1px solid var(--grid);
    vertical-align: middle;
  }

  /* Column sizing (3 columns) */
  .col-group   { width: 180px; } /* left grouped label (e.g., 1.2 Organization info) */
  .col-label   { width: 180px; } /* middle field label (e.g., Acronym) */
  .col-value   { width: auto; }  /* right blank value cell */

  /* Left grey group cells */
  .group-cell{
    background: var(--label1);
    font-weight: 700;
    padding: 8px;
    line-height: 1.2;
  }

  /* Middle label cells */
  .field-label{
    background: var(--label2);
    padding: 6px 8px;
  }

  /* Right empty (value) cells */
  .field-value{
    padding: 6px 8px;
    background:#fff;
  }

  /* Small footnote marker style */
  .sup{
    font-size: 10px;
    vertical-align: super;
  }

  /* Make it nice on screens narrower than A4 */
  @media (max-width: 900px){
    .page{ padding: 16px; }
  }
/* --- Section 2 helpers --- */
.note-cell{
  background: var(--label1);
  padding: 6px 8px;
  font-style: italic;
  font-size: 11px;
  line-height: 1.25;
}
.big-field   { height: 220px; }   /* Rationale/justification box */
.medium-field{ height: 150px; }   /* Expected results box */
.spacer      { height: 22px; }
/* --- Section 3 table --- */
.band { background:#f7d186; }         /* the light orange rows */
.center { text-align:center; }
.nowrap { white-space:nowrap; }
.small { font-size:11px; }
.top-note {
  border:1px solid var(--grid);
  padding:8px;
  margin-top:6px;
  font-size:11px;
  line-height:1.35;
  background:#fff;
}


