/* Column sizing (10 columns total) */
.col-level    { width:92px; }
.col-activity { width:200px; }
.col-q        { width:50px; }    /* Q1..Q4 */
.col-cso      { width:100px; }
.col-cash     { width:100px; }
.col-total    { width:100px; }
.col-supply   { width:100px; }

/* Print behavior */
table{ page-break-inside:auto; }
thead{ display:table-header-group; }  /* repeat header on each page */
tr{ page-break-inside:avoid; }

/* === PRINT LAYOUT: fill the page, no mini-scaling === */
@media print {
  @page { size: A4; margin: 10mm; }       /* adjust margins as you like */
  html, body { width: 210mm; height: 297mm; margin: 0; }
  /* Frappe wrappers sometimes constrain width; neutralize them */
  .print-format, .pf-content, .page {
    width: auto !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
  }
  /* Tables should span the printable area */
  .doc-table { width: 100% !important; table-layout: fixed; }
  .doc-table td, .doc-table th { padding: 6px 8px; }
  body { font-size: 11px; }               /* bump if needed */
}
/* Section notes */
.note-wide {
  padding: 6px 8px;
  font-size: 12px;
  line-height: 1.35;
}

/* Signature row */
.signature-cell {
  height: 60px;              /* space for writing */
  vertical-align: bottom;
  padding: 12px 8px;
}
/* --- Page-break control for Section 3 --- */
@media print {
  /* general safety for headers */
  thead { display: table-header-group; }

  /* use on rows you don't want to split across pages */
  .no-row-break { break-inside: avoid; page-break-inside: avoid; }

  /* use on a row that must stay with the next row (e.g., PD Output with first activity) */
  .keep-with-next { break-after: avoid-page; page-break-after: avoid; }
}
/* Signature layout */
.signature-box {
  height: 100px;               /* space for signing */
  vertical-align: bottom;
  padding: 12px;
}
.signature-line {
  display: block;
  border-top: 1px solid #000;
  margin-top: 40px;            /* where the actual signature line is */
  text-align: center;
  font-size: 11px;
  color: #333;
}
